import heapq


def minCostWithCoupons(n, roads, k):
    if n == 1:
        return 0
    adj = [[] for _ in range(n)]
    for a, b, w in roads:
        adj[a].append((b, w))
        adj[b].append((a, w))
    INF = float('inf')
    dist = [[INF] * (k + 1) for _ in range(n)]
    dist[0][0] = 0
    heap = [(0, 0, 0)]
    while heap:
        d, u, j = heapq.heappop(heap)
        if d > dist[u][j]:
            continue
        if u == n - 1:
            return d
        for v, w in adj[u]:
            if d + w < dist[v][j]:
                dist[v][j] = d + w
                heapq.heappush(heap, (d + w, v, j))
            if j < k and d + w // 2 < dist[v][j + 1]:
                dist[v][j + 1] = d + w // 2
                heapq.heappush(heap, (d + w // 2, v, j + 1))
    return -1
